{"explanation":"The discriminant Δ = b² − 4ac is the part under the square root in the quadratic formula x = (−b ± √Δ)/(2a). If Δ > 0, ± gives two different real roots and the parabola crosses the x-axis twice. If Δ = 0, ± adds nothing, so there is one repeated root and the vertex just touches the axis. If Δ < 0, a negative number has no real square root, so the parabola never reaches the x-axis. Move the a, b, c sliders to see this (a = 1, b = 2, c = 1 gives Δ = 0 exactly).","manimCode":"const XMIN = -6, XMAX = 6, YMIN = -5, YMAX = 5;
const ax = new Axes({ xRange: [XMIN, XMAX, 1], yRange: [YMIN, YMAX, 1], xLength: 7.5, yLength: 6.2, tips: false });
scene.add(ax);

const formula = new MathTex({ latex: 'y = ax^2 + bx + c' });
await formula.waitForRender();
formula.scale(0.8);
formula.moveTo([-5.0, 3.5, 0]);
const formula2 = new MathTex({ latex: '\\Delta = b^2 - 4ac' });
await formula2.waitForRender();
formula2.scale(0.8);
formula2.moveTo([-5.0, 2.7, 0]);
scene.add(formula, formula2);

let a = 1, b = 0, c = -2;
let curveGroup = null;
let rootDots = [];
let vertexDot = null;
let deltaText = null;
let statusText = null;
let rootsText = null;

function f(x) { return a * x * x + b * x + c; }

function buildCurve(col) {
  // plot only the runs where the curve stays inside the y-range
  const N = 400;
  const parts = [];
  let runStart = null;
  let prevX = XMIN;
  for (let i = 0; i <= N; i++) {
    const x = XMIN + (XMAX - XMIN) * i / N;
    const y = f(x);
    const inside = y >= YMIN && y <= YMAX;
    if (inside && runStart === null) runStart = x;
    if ((!inside || i === N) && runStart !== null) {
      const end = inside ? x : prevX;
      if (end - runStart > 0.02) {
        parts.push(ax.plot(f, { color: col, xRange: [runStart, end], numSamples: 200 }));
      }
      runStart = null;
    }
    prevX = x;
  }
  return new VGroup(...parts);
}

function makeText(str, col, size, pos) {
  const t = new Text({ text: str, color: col, fontSize: size });
  t.moveTo(pos);
  scene.add(t);
  return t;
}

function fmt(v) { return (Math.abs(v) < 1e-9 ? 0 : v).toFixed(2); }

function update() {
  if (curveGroup) scene.remove(curveGroup);
  rootDots.forEach(d => scene.remove(d));
  rootDots = [];
  if (vertexDot) scene.remove(vertexDot);
  vertexDot = null;
  if (deltaText) scene.remove(deltaText);
  if (statusText) scene.remove(statusText);
  if (rootsText) scene.remove(rootsText);

  const D = b * b - 4 * a * c;
  const isQuad = Math.abs(a) > 1e-9;
  let col, status, rootsStr = '';
  if (!isQuad) {
    col = GRAY; status = 'a = 0: not a quadratic';
  } else if (Math.abs(D) < 1e-9) {
    col = YELLOW; status = 'Δ = 0 → one real root';
    const r = -b / (2 * a);
    rootsStr = 'x = ' + fmt(r);
    if (r >= XMIN && r <= XMAX) rootDots.push(new Dot({ point: ax.c2p(r, 0), color: YELLOW, radius: 0.12 }));
  } else if (D > 0) {
    col = GREEN; status = 'Δ > 0 → two real roots';
    const s = Math.sqrt(D);
    const r1 = (-b - s) / (2 * a), r2 = (-b + s) / (2 * a);
    rootsStr = 'x = ' + fmt(Math.min(r1, r2)) + ',  ' + fmt(Math.max(r1, r2));
    [r1, r2].forEach(r => {
      if (r >= XMIN && r <= XMAX) rootDots.push(new Dot({ point: ax.c2p(r, 0), color: GREEN, radius: 0.12 }));
    });
  } else {
    col = RED; status = 'Δ < 0 → no real roots';
    rootsStr = 'parabola misses the x-axis';
  }

  curveGroup = buildCurve(isQuad ? BLUE : GRAY);
  scene.add(curveGroup);

  if (isQuad) {
    const vx = -b / (2 * a), vy = f(vx);
    if (vx >= XMIN && vx <= XMAX && vy >= YMIN && vy <= YMAX) {
      vertexDot = new Dot({ point: ax.c2p(vx, vy), color: col, radius: 0.07 });
      scene.add(vertexDot);
    }
  }
  rootDots.forEach(d => scene.add(d));

  deltaText = makeText('Δ = ' + fmt(b * b) + ' − ' + fmt(4 * a * c) + ' = ' + fmt(D), WHITE, 22, [4.9, -1.2, 0]);
  statusText = makeText(status, col, 24, [4.9, -1.9, 0]);
  rootsText = makeText(rootsStr, col, 20, [4.9, -2.6, 0]);
}

update();

const controls = new Controls(scene, { position: 'top-right' });
controls.addSlider({ label: 'a', min: -2, max: 2, value: 1, step: 0.1, onChange: (v) => { a = Math.round(v * 10) / 10; update(); } });
controls.addSlider({ label: 'b', min: -5, max: 5, value: 0, step: 0.1, onChange: (v) => { b = Math.round(v * 10) / 10; update(); } });
controls.addSlider({ label: 'c', min: -4, max: 4, value: -2, step: 0.1, onChange: (v) => { c = Math.round(v * 10) / 10; update(); } });

await scene.wait(999999);"}

